 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
            r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
            # Keep only rectangular hollow frames, allowing noisy cells inside as separate contents.
            if all(g[r0][x] == color and g[r1][x] == color for x in range(c0,c1+1)) and all(g[y][c0] == color and g[y][c1] == color for y in range(r0,r1+1)):
                objs.append((color,r0,r1,c0,c1))
    # Identify the uniquely patterned frame: any nonzero interior cells belonging to other colors.
    patterned = []
    for ob in objs:
        color,r0,r1,c0,c1 = ob
        interior = [[g[y][x] for x in range(c0+1,c1)] for y in range(r0+1,r1)]
        if any(v != 0 for row in interior for v in row):
            patterned.append((ob,interior))
    if len(patterned) != 1:
        return g
    (src, pat) = patterned[0]
    scolor,sr0,sr1,sc0,sc1 = src
    shape = (sr1-sr0+1, sc1-sc0+1)
    # Source contains the pattern and remains unchanged. Copy it into matching blank frames;
    # remove frames of other dimensions, which are distractors.
    for color,r0,r1,c0,c1 in objs:
        if (color,r0,r1,c0,c1) == src:
            continue
        if (r1-r0+1,c1-c0+1) == shape:
            for iy,row in enumerate(pat):
                for ix,v in enumerate(row):
                    g[r0+1+iy][c0+1+ix] = color if v != 0 else 0
        else:
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    if g[y][x] == color:
                        g[y][x] = 0
    return g

